// Autoloader
// ----------
// Loads the saved recipes and ingredients (from data/storage.js) automatically when the
// app starts, and shares them with every screen so no screen has to load them itself.
//
// How it works:
//   1. src/app/_layout.tsx wraps the whole app in <Autoloader>.
//   2. When <Autoloader> is first created, it reads recipes.json and ingredients.json.
//   3. Any screen can then get the loaded data with the useLoadedData() hook:
//        const { recipes, ingredients, error, reload } = useLoadedData();
//        - recipes:     Recipe[]      (all saved recipes)
//        - ingredients: Ingredient[]  (all saved ingredients)
//        - error:       null, or the error if loading failed
//        - reload():    reads the files again; call it after saveRecipe, saveIngredient,
//                       deleteRecipe, or deleteIngredient so the screens show the change.

import { createContext, useCallback, useContext, useState } from 'react';

import { loadAll } from 'data/storage';

// What the app uses when nothing has been loaded (or loading failed)
const EMPTY = { recipes: [], ingredients: [] };

// A React "context" lets any screen inside <Autoloader> read the same data
// without passing it down through props. The value here is only a fallback
// for components that are rendered outside <Autoloader>.
const LoadedDataContext = createContext({ ...EMPTY, error: null, reload: () => {} });

// Read both files. If anything goes wrong, return empty lists instead of crashing the app.
function safeLoadAll() {
  try {
    const data = loadAll();
    // Shows up in the terminal running "npx expo", so you can see what was loaded
    console.log(
      `Autoloader: loaded ${data.recipes.length} recipes, ${data.ingredients.length} ingredients`
    );
    return { ...data, error: null };
  } catch (error) {
    console.warn('Autoloader: could not load saved data', error);
    return { ...EMPTY, error };
  }
}

// The component that does the loading. Put it around the app (done in src/app/_layout.tsx).
export function Autoloader({ children }) {
  // Passing the function itself (not calling it) makes React run it only once, on startup.
  // storage.js reads files synchronously, so the data is ready before the first screen renders.
  const [data, setData] = useState(safeLoadAll);

  // Re-read the files and update every screen that uses useLoadedData().
  // useCallback keeps the same function between renders.
  const reload = useCallback(() => setData(safeLoadAll()), []);

  return (
    <LoadedDataContext.Provider value={{ ...data, reload }}>
      {children}
    </LoadedDataContext.Provider>
  );
}

// Hook for screens: const { recipes, ingredients, reload } = useLoadedData();
export function useLoadedData() {
  return useContext(LoadedDataContext);
}

